{
    MORPHO.accrueInterest(marketParams);

    market = MORPHO.market(id);
    shares = MORPHO.supplyShares(id, address(this));
    assets = shares.toAssetsDown(market.totalSupplyAssets, market.totalSupplyShares);
}

